// Avatar tests: the Swift port draws the Deck's identity marks byte for byte (ADR 0043).
//
// Every expected SVG below was printed by the Deck's own renderers at native-core a1d8ac72
// (deck/js/avatars.js avatarSource over web/vendor/vyrecode), from node, and pasted here
// unchanged: the edges (all-zero and all-0xff fingerprints, an empty seed, a unicode project
// name), every person look, every project colour and mark, solid and draft, and every teammate
// role at both badge sizes. Synthetic seeds only, from the sample world.

import AppKit
import Foundation

/// Equal strings, or a failure naming where they part.
private func same(_ t: Suite, _ got: String, _ want: String, _ note: String, line: UInt = #line) {
    if got == want { t.ok(true); return }
    let g = Array(got.utf16), w = Array(want.utf16)
    var i = 0
    while i < min(g.count, w.count) && g[i] == w[i] { i += 1 }
    let at = { (u: [UInt16]) in String(decoding: u[max(0, i - 40)..<min(u.count, i + 40)], as: UTF16.self) }
    t.ok(false, "\(note): differs at \(i)\n  got  \(at(g))\n  want \(at(w))", line: line)
}

private func pixel(_ image: NSImage, _ x: Int, _ y: Int) -> NSColor? {
    (image.representations.first as? NSBitmapImageRep)?.colorAt(x: x, y: y)
}

// capsule-suite: avatarSuite
let avatarSuite = Suite("avatars") { t in
    t.test("the pasted vectors are all here") {
        t.eq(avatarPersonVectors.count, 11); t.eq(avatarRingVectors.count, 6); t.eq(avatarAssistantVectors.count, 10)
        t.eq(avatarAgentVectors.count, 10); t.eq(avatarTeammateVectors.count, 26); t.eq(avatarProjectVectors.count, 24)
        t.eq(Set(avatarProjectBytes.map { $0.2 }).count, 8, "every project colour")
        t.eq(Set(avatarProjectBytes.map { Int($0.1[1]) % 6 }).count, 6, "every project mark")
        t.eq(Set(avatarFingerprints.map { Int($0.1[0]) % 4 }).count, 4, "every person look")
    }

    t.test("numbers print as JavaScript prints them") {
        for (bits, want) in avatarNumbers { t.eq(JSNumber.string(Double(bitPattern: bits)), want) }
        t.eq(JSNumber.round(2.5), 3); t.eq(JSNumber.round(-2.5), -2); t.eq(JSNumber.round(0.49999999999999994), 0)
        t.eq(JSNumber.round(254.5), 255); t.eq(JSNumber.round(3.4999), 3)
    }

    t.test("the trig table is V8's, within a bit of this Mac's libm") {
        var angles: [(Double, (UInt64, UInt64))] = [(-Double.pi / 2, AvatarTrig.marker)]
        for i in 0..<8 { angles.append((Double(i) / 8 * Double.pi * 2, AvatarTrig.creature[i])) }
        for i in 0..<10 { angles.append((Double(i) / 10 * Double.pi * 2, AvatarTrig.blob[i])) }
        for i in 0..<36 { angles.append(((Double(i) * 10 - 90) * Double.pi / 180, AvatarTrig.ring[i])) }
        for (a, bits) in angles {
            let v = AvatarTrig.at(bits)
            t.ok(abs(v.cos - cos(a)) <= cos(a).ulp.magnitude * 2 + 1e-300, "cos \(a)")
            t.ok(abs(v.sin - sin(a)) <= sin(a).ulp.magnitude * 2 + 1e-300, "sin \(a)")
        }
    }

    t.test("fingerprints decode from system.info's base64url; anything else is nil") {
        for (s, bytes) in avatarFingerprints { t.eq(Avatars.fingerprintBytes(s), bytes, s) }
        for bad in [nil, "", "AAAAAAAAAA", "AAAAAAAAAAAA", "AAAAAAAAAA=", "AAAAAAAAAA+", "AAAAAAAAAA/", "0011223344556677", "AAAAAAAAAAé"] {
            t.ok(Avatars.fingerprintBytes(bad) == nil, String(describing: bad))
        }
        t.eq(Avatars.fingerprintBytes("__________-"), [255, 255, 255, 255, 255, 255, 255, 255], "the spare bits are ignored, as atob does")
    }

    t.test("project bytes, colours, inks and teammate ids match the Deck") {
        for (seed, bytes, color) in avatarProjectBytes {
            t.eq(Avatars.projectBytes(seed), bytes, seed)
            t.eq(Avatars.projectColor(seed), color, seed)
        }
        for (hex, ink, rim) in avatarInks {
            t.eq(AvatarSVG.featureInk(hex), ink, hex)
            t.eq(AvatarSVG.needsRim(hex), rim, hex)
        }
        for (role, project, id) in avatarTeammateIds { t.eq(Avatars.teammateId(role: role, project: project), id) }
        t.eq(Avatars.projectSeed(slug: "harlow-legal", avatarSeed: nil), "harlow-legal")
        t.eq(Avatars.projectSeed(slug: "harlow-legal", avatarSeed: ""), "harlow-legal")
        t.eq(Avatars.projectSeed(slug: "harlow-legal", avatarSeed: "t_01HZX3K9QW"), "t_01HZX3K9QW")
    }

    t.test("the codeword is payload.js's: CRC-8 and Reed-Solomon parity") {
        let cw = AvatarCodeword.build([0, 0, 0, 0, 0, 0, 0, 0])
        t.eq(cw.count, 18)
        t.eq(Array(cw.prefix(9)), [0, 0, 0, 0, 0, 0, 0, 0, 0], "a zero id has a zero CRC and zero parity")
        t.eq(AvatarSVG.levels([1, 2, 3, 4, 5, 6, 7, 8]).count, 72)
    }

    t.test("person circles match the Deck byte for byte") {
        for (fp, seed, svg) in avatarPersonVectors {
            same(t, Avatars.source(.person, seed: seed, px: 120, fingerprint: Avatars.fingerprintBytes(fp)), svg, "person \(fp ?? seed)")
        }
    }

    t.test("Vyre code rings match the Deck byte for byte") {
        for (fp, svg) in avatarRingVectors {
            same(t, Avatars.source(.person, seed: "x", px: 120, fingerprint: Avatars.fingerprintBytes(fp), ring: true), svg, "ring \(fp)")
        }
    }

    t.test("assistant creatures match the Deck byte for byte") {
        for (seed, svg) in avatarAssistantVectors { same(t, Avatars.source(.assistant, seed: seed, px: 120), svg, "assistant \(seed)") }
    }

    t.test("agent blobs match the Deck byte for byte") {
        for (seed, svg) in avatarAgentVectors { same(t, Avatars.source(.agent, seed: seed, px: 120), svg, "agent \(seed)") }
    }

    t.test("teammate characters match the Deck byte for byte, badges at 40 only") {
        for (id, project, px, svg) in avatarTeammateVectors {
            let color = project.map(Avatars.projectColor)
            same(t, Avatars.source(.teammate, seed: id, px: px, color: color), svg, "teammate \(id) \(px)")
        }
    }

    t.test("project tiles match the Deck byte for byte, solid and draft") {
        for (seed, draft, svg) in avatarProjectVectors {
            same(t, Avatars.source(.project, seed: seed, px: 120, draft: draft), svg, "project \(seed) \(draft)")
        }
    }

    t.test("kinds take the Deck's seeds and sizes") {
        let (b64, bytes) = avatarFingerprints[2]
        let hex = bytes.map { String(format: "%02x", $0) }.joined()
        t.eq(Avatars.svg(.assistant(fingerprint8: b64, name: "juno"), size: 24), Avatars.source(.assistant, seed: hex, px: 120))
        t.eq(Avatars.svg(.assistant(fingerprint8: nil, name: "juno"), size: 24), Avatars.source(.assistant, seed: "vyre:assistant:fallback:juno", px: 120))
        t.eq(Avatars.svg(.assistant(fingerprint8: "short", name: ""), size: 24), Avatars.source(.assistant, seed: "vyre:assistant:fallback:vyre", px: 120))
        t.eq(Avatars.svg(.person(fingerprint8: nil, name: "alex"), size: 24), avatarPersonVectors.first { $0.seed == "vyre:person:fallback:alex" }?.svg)
        t.eq(Avatars.svg(.person(fingerprint8: nil, name: nil), size: 24), avatarPersonVectors.first { $0.seed == "vyre:person:fallback:you" }?.svg)
        // The ring: asked for, 96 and up, and only with a real fingerprint.
        let ringed = avatarRingVectors[0]
        t.eq(Avatars.svg(.person(fingerprint8: ringed.fp, name: "alex"), size: 96, ring: true), ringed.svg)
        t.ok(!Avatars.svg(.person(fingerprint8: ringed.fp, name: "alex"), size: 95, ring: true).contains("600"), "no ring below 96")
        t.ok(!Avatars.svg(.person(fingerprint8: nil, name: "alex"), size: 200, ring: true).contains("600"), "no ring without a fingerprint")
        t.ok(!Avatars.svg(.person(fingerprint8: ringed.fp, name: "alex"), size: 200).contains("600"), "no ring unless asked")
        // A teammate wears its project's colour, and draws its 24 or 40 drawing by size.
        let mate = avatarTeammateVectors.first { $0.id == "design-harlow-legal" && $0.px == 40 }!
        t.eq(Avatars.svg(.teammate("design-harlow-legal", projectSeed: "harlow-legal"), size: 32), mate.svg)
        let small = avatarTeammateVectors.first { $0.id == "design-harlow-legal" && $0.px == 24 }!
        t.eq(Avatars.svg(.teammate("design-harlow-legal", projectSeed: "harlow-legal"), size: 31), small.svg)
        t.eq(Avatars.svg(.agent("kit"), size: 24), avatarAgentVectors[0].svg)
        t.eq(Avatars.svg(.project(seed: "harlow-legal", draft: true), size: 20), avatarProjectVectors[1].svg)
        t.ok(Avatars.key(.teammate("kit", projectSeed: nil), size: 24, ring: false) != Avatars.key(.teammate("kit", projectSeed: nil), size: 40, ring: false))
        t.eq(Avatars.key(.agent("kit"), size: 24, ring: true), Avatars.key(.agent("kit"), size: 40, ring: false))
    }

    t.test("every family renders through AppKit's SVG, at the asked size, without a window") {
        MainActor.assumeIsolated {
            let images = AvatarImages(limit: 16)
            let kinds: [AvatarKind] = [
                .person(fingerprint8: avatarFingerprints[2].0, name: "alex"), .assistant(fingerprint8: avatarFingerprints[3].0, name: "juno"),
                .agent("kit"), .teammate("design-harlow-legal", projectSeed: "harlow-legal"),
                .project(seed: "northwind-bakery", draft: false), .project(seed: "t_01HZX3K9QW", draft: true),
            ]
            for kind in kinds {
                guard let image = images.image(kind, size: 24, scale: 2) else { t.ok(false, "\(kind) did not render"); continue }
                t.eq(image.size, NSSize(width: 24, height: 24))
                t.eq((image.representations.first as? NSBitmapImageRep)?.pixelsWide, 48)
                t.ok(images.image(kind, size: 24, scale: 2) === image, "cached")
            }
            // Drawn, not blank: the person's centre is its gradient, a solid tile's corner is empty.
            let person = images.image(kinds[0], size: 24, scale: 2)!
            t.ok((pixel(person, 24, 24)?.alphaComponent ?? 0) > 0.99, "the person's centre is painted")
            t.ok((pixel(person, 0, 0)?.alphaComponent ?? 1) < 0.01, "outside the circle is clear")
            let tile = images.image(kinds[4], size: 24, scale: 2)!
            t.ok((pixel(tile, 24, 4)?.alphaComponent ?? 0) > 0.99, "a solid tile is filled")
            let draft = images.image(kinds[5], size: 24, scale: 2)!
            t.ok((pixel(draft, 12, 12)?.alphaComponent ?? 1) < 0.01, "a draft tile is unfilled")
            let ring = images.image(kinds[0], size: 120, ring: true, scale: 1)!
            t.ok((pixel(ring, 1, 1)?.alphaComponent ?? 0) > 0.99, "the ring's ground fills its square")
            t.ok(AvatarImages.render("not svg", size: 24, scale: 2) == nil, "a bad source is nil, not a crash")
        }
    }
}

